def background(grid):
    """The most common color in the grid."""
    return Counter(v for row in grid for v in row).most_common(1)[0][0]

def components(grid, bg=None):
    """All 4-connected same-color components of non-background cells, as (color, cells)."""
    if bg is None: bg = background(grid)
    H, W = len(grid), len(grid[0])
    seen = [[False] * W for _ in range(H)]; out = []
    for i in range(H):
        for j in range(W):
            if grid[i][j] == bg or seen[i][j]: continue
            c = grid[i][j]; q = deque([(i, j)]); seen[i][j] = True; cells = []
            while q:
                a, b = q.popleft(); cells.append((a, b))
                for di, dj in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    x, y = a + di, b + dj
                    if 0 <= x < H and 0 <= y < W and not seen[x][y] and grid[x][y] == c:
                        seen[x][y] = True; q.append((x, y))
            out.append((c, cells))
    return out

def bbox(cells):
    """The (top, bottom, left, right) bounds of a list of (row, col) cells."""
    rs = [a for a, b in cells]; cs = [b for a, b in cells]
    return min(rs), max(rs), min(cs), max(cs)

def solid_rect_components(grid, bg=None, min_size=4, min_fill=0.6):
    """Multi-cell components that are nearly solid rectangles, as (color, top, bottom, left, right)."""
    if bg is None: bg = background(grid)
    objs = []
    for c, cells in components(grid, bg):
        if len(cells) >= min_size:
            r0, r1, c0, c1 = bbox(cells)
            if len(cells) / ((r1 - r0 + 1) * (c1 - c0 + 1)) >= min_fill:
                objs.append((c, r0, r1, c0, c1))
    return objs

def fill_noise_to_rects(grid, min_size=4, min_fill=0.6):
    """Each near-solid rectangle component fills its bounding box with its color; every other non-background cell becomes background."""
    H, W = len(grid), len(grid[0])
    bg = background(grid)
    out = [[bg] * W for _ in range(H)]
    for c, r0, r1, c0, c1 in solid_rect_components(grid, bg, min_size, min_fill):
        for i in range(r0, r1 + 1):
            for j in range(c0, c1 + 1):
                out[i][j] = c
    return out
